	refresh: function(frm) {
		if (!frm.is_new()) {
			// Add custom buttons
			frm.add_custom_button(__('Schedule Appointment'), function() {
				frappe.new_doc('Appointment', {
					patient: frm.doc.name,
					patient_name: frm.doc.patient_name
				});
			}, __('Actions'));

			frm.add_custom_button(__('New Session'), function() {
