frappe.ui.form.on('Appointment', {
	refresh: function(frm) {
		if (!frm.is_new()) {
			// Add action buttons based on status
			if (frm.doc.status === 'Scheduled') {
				frm.add_custom_button(__('Check In'), function() {
					frm.trigger('check_in_patient');
				}).addClass('btn-primary');

				frm.add_custom_button(__('Cancel Appointment'), function() {
					frm.trigger('cancel_appointment');
				});
			}

			if (frm.doc.status === 'Checked In') {
				frm.add_custom_button(__('Create Session'), function() {
					frm.trigger('create_dialysis_session');
				}).addClass('btn-success');
			}

			// Show appointment timeline
			frm.trigger('show_appointment_info');
		}

		// Set indicator
		frm.trigger('set_status_indicator');

		// Check slot availability when form loads
		if (frm.is_new()) {
			frm.trigger('check_slot_availability');
		}
	},

	check_in_patient: function(frm) {
		frappe.confirm(
			__('Check in patient {0} for this appointment?', [frm.doc.patient_name]),
			function() {
				frappe.call({
					method: 'dialysis_center.appointment_scheduling.doctype.appointment.appointment.check_in_appointment',
					args: {
						appointment: frm.doc.name
					},
					callback: function(r) {
						frm.reload_doc();
						frappe.show_alert({
							message: __('Patient checked in successfully'),
							indicator: 'green'
						});
					}
				});
			}
		);
	},

	cancel_appointment: function(frm) {
		frappe.prompt({
			label: __('Cancellation Reason'),
			fieldname: 'reason',
			fieldtype: 'Small Text',
			reqd: 1
		}, function(values) {
			frappe.call({
				method: 'frappe.client.set_value',
				args: {
					doctype: 'Appointment',
					name: frm.doc.name,
					fieldname: {
						status: 'Cancelled',
						notes: (frm.doc.notes || '') + '\nCancellation Reason: ' + values.reason
					}
				},
				callback: function(r) {
					frm.reload_doc();
					frappe.show_alert({
						message: __('Appointment cancelled'),
						indicator: 'red'
					});
				}
			});
		}, __('Cancel Appointment'));
	},

	create_dialysis_session: function(frm) {
		frappe.new_doc('Dialysis Session', {
			patient: frm.doc.patient,
			patient_name: frm.doc.patient_name,
			appointment: frm.doc.name,
			session_date: frm.doc.appointment_date,
			session_time: frm.doc.appointment_time,
			dialysis_machine: frm.doc.machine,
			treatment_duration: frm.doc.duration
		});
	},

	show_appointment_info: function(frm) {
		if (!frm.doc.appointment_date) return;

		let info_html = `
			<div class="appointment-info" style="padding: 10px; background: #f8f9fa; border-radius: 5px; margin: 10px 0;">
				<div class="row">
					<div class="col-sm-6">
						<strong>${__('Date')}:</strong> ${frappe.datetime.str_to_user(frm.doc.appointment_date)}<br>
						<strong>${__('Time')}:</strong> ${frm.doc.appointment_time || 'Not set'}
					</div>
					<div class="col-sm-6">
						<strong>${__('Duration')}:</strong> ${frm.doc.duration || 0} minutes<br>
						<strong>${__('Machine')}:</strong> ${frm.doc.machine || 'Not assigned'}
					</div>
				</div>
			</div>
		`;

		frm.dashboard.add_comment(info_html, true);
	},

	set_status_indicator: function(frm) {
		const status_colors = {
			'Scheduled': 'blue',
			'Checked In': 'orange',
			'In Progress': 'purple',
			'Completed': 'green',
			'Cancelled': 'red'
		};

		if (frm.doc.status) {
			frm.page.set_indicator(frm.doc.status, status_colors[frm.doc.status] || 'gray');
		}
	},

	check_slot_availability: function(frm) {
		if (frm.doc.appointment_date && frm.doc.machine && frm.doc.appointment_time) {
			frappe.call({
				method: 'frappe.client.get_count',
				args: {
					doctype: 'Appointment',
					filters: {
						appointment_date: frm.doc.appointment_date,
						machine: frm.doc.machine,
						appointment_time: frm.doc.appointment_time,
						status: ['not in', ['Cancelled', 'Completed']]
					}
				},
				callback: function(r) {
					if (r.message > 0) {
						frappe.msgprint({
							title: __('Slot Conflict'),
							message: __('This time slot may already be booked for this machine'),
							indicator: 'orange'
						});
					}
				}
			});
		}
	},

	patient: function(frm) {
		if (frm.doc.patient) {
			// Fetch patient's default duration
			frappe.db.get_value('Patient', frm.doc.patient, ['duration', 'patient_name'], function(r) {
				if (r && r.duration) {
					frm.set_value('duration', r.duration);
				}
				if (r && r.patient_name) {
					frm.set_value('patient_name', r.patient_name);
				}
			});
		}
	},

	appointment_date: function(frm) {
		frm.trigger('check_slot_availability');
	},

	machine: function(frm) {
		frm.trigger('check_slot_availability');

		// Check machine status
		if (frm.doc.machine) {
			frappe.db.get_value('Dialysis Machine', frm.doc.machine, 'status', function(r) {
				if (r && r.status !== 'Available') {
					frappe.msgprint({
						title: __('Machine Status'),
						message: __('Warning: Machine status is {0}', [r.status]),
						indicator: 'orange'
					});
				}
			});
		}
	},

	appointment_time: function(frm) {
		frm.trigger('check_slot_availability');

		// Calculate end time
		if (frm.doc.appointment_time && frm.doc.duration) {
			let time_parts = frm.doc.appointment_time.split(':');
			let minutes = parseInt(time_parts[0]) * 60 + parseInt(time_parts[1]) + frm.doc.duration;
			let end_hours = Math.floor(minutes / 60);
			let end_minutes = minutes % 60;
			frm.set_value('appointment_end_time', 
				`${String(end_hours).padStart(2, '0')}:${String(end_minutes).padStart(2, '0')}:00`);
		}
	},

	duration: function(frm) {
		frm.trigger('appointment_time');
	}
});
EOF
"}

{"command": "cat > frappe-bench/apps/dialysis_center/dialysis_center/billing_management/doctype/invoice/invoice.js << 'EOF'
frappe.ui.form.on('Invoice', {
	refresh: function(frm) {
		if (!frm.is_new()) {
			// Add payment button
			if (frm.doc.payment_status !== 'Paid' && frm.doc.docstatus === 1) {
				frm.add_custom_button(__('Record Payment'), function() {
					frm.trigger('record_payment');
				}).addClass('btn-primary');
			}

			// Add print button
			frm.add_custom_button(__('Print Invoice'), function() {
				frm.print_doc();
			});

			// Show payment status
			frm.trigger('show_payment_info');
		}

		// Set indicator
		frm.trigger('set_status_indicator');
	},

	record_payment: function(frm) {
		frappe.new_doc('Payment', {
			invoice: frm.doc.name,
			patient: frm.doc.patient,
			patient_name: frm.doc.patient_name,
			amount: frm.doc.outstanding_amount
		});
	},

	show_payment_info: function(frm) {
		let payment_html = `
			<div class="payment-summary" style="padding: 15px; background: #f8f9fa; border-radius: 5px; margin: 10px 0;">
				<div class="row">
					<div class="col-sm-4">
						<h6>${__('Total Amount')}</h6>
						<h4>${format_currency(frm.doc.total_amount || 0)}</h4>
					</div>
					<div class="col-sm-4">
						<h6>${__('Amount Paid')}</h6>
						<h4 style="color: green;">${format_currency(frm.doc.amount_paid || 0)}</h4>
					</div>
					<div class="col-sm-4">
						<h6>${__('Outstanding')}</h6>
						<h4 style="color: ${(frm.doc.outstanding_amount || 0) > 0 ? 'red' : 'green'};">
							${format_currency(frm.doc.outstanding_amount || 0)}
						</h4>
					</div>
				</div>
			</div>
		`;

		frm.dashboard.add_comment(payment_html, true);
	},

	set_status_indicator: function(frm) {
		const status_colors = {
			'Draft': 'gray',
			'Unpaid': 'red',
			'Partially Paid': 'orange',
			'Paid': 'green',
			'Cancelled': 'red'
		};

		if (frm.doc.payment_status) {
			frm.page.set_indicator(frm.doc.payment_status, status_colors[frm.doc.payment_status] || 'blue');
		}
	},

	before_save: function(frm) {
		frm.trigger('calculate_totals');
	},

	calculate_totals: function(frm) {
		let subtotal = 0;

		// Calculate subtotal from items
		if (frm.doc.invoice_items) {
			frm.doc.invoice_items.forEach(item => {
				if (item.quantity && item.rate) {
					item.amount = item.quantity * item.rate;
					subtotal += item.amount;
				}
			});
		}

		frm.set_value('subtotal', subtotal);

		// Calculate discount
		let discount = 0;
		if (frm.doc.discount_percentage) {
			discount = (subtotal * frm.doc.discount_percentage) / 100;
		} else if (frm.doc.discount_amount) {
			discount = frm.doc.discount_amount;
		}
		frm.set_value('discount_amount', discount);

		// Calculate tax
		let taxable_amount = subtotal - discount;
		let tax = 0;
		if (frm.doc.tax_percentage) {
			tax = (taxable_amount * frm.doc.tax_percentage) / 100;
		} else if (frm.doc.tax_amount) {
			tax = frm.doc.tax_amount;
		}
		frm.set_value('tax_amount', tax);

		// Calculate total
		let total = taxable_amount + tax;
		frm.set_value('total_amount', total);

		// Calculate outstanding
		let outstanding = total - (frm.doc.amount_paid || 0);
		frm.set_value('outstanding_amount', outstanding);

		// Update payment status
		frm.trigger('update_payment_status');
	},

	update_payment_status: function(frm) {
		if (!frm.doc.total_amount) {
			frm.set_value('payment_status', 'Draft');
		} else if (frm.doc.outstanding_amount <= 0) {
			frm.set_value('payment_status', 'Paid');
		} else if (frm.doc.amount_paid > 0) {
			frm.set_value('payment_status', 'Partially Paid');
		} else {
			frm.set_value('payment_status', 'Unpaid');
		}
	},

	discount_percentage: function(frm) {
		if (frm.doc.discount_percentage) {
			frm.set_value('discount_amount', 0);
		}
		frm.trigger('calculate_totals');
	},

	discount_amount: function(frm) {
		if (frm.doc.discount_amount) {
			frm.set_value('discount_percentage', 0);
		}
		frm.trigger('calculate_totals');
	},

	tax_percentage: function(frm) {
		frm.trigger('calculate_totals');
	},

	patient: function(frm) {
		if (frm.doc.patient) {
			frappe.db.get_value('Patient', frm.doc.patient, 'patient_name', function(r) {
				if (r && r.patient_name) {
					frm.set_value('patient_name', r.patient_name);
				}
			});
		}
	},

	dialysis_session: function(frm) {
		if (frm.doc.dialysis_session) {
			// Auto-add session as invoice item
			frappe.call({
				method: 'frappe.client.get',
				args: {
					doctype: 'Dialysis Session',
					name: frm.doc.dialysis_session
				},
				callback: function(r) {
					if (r.message) {
						let row = frm.add_child('invoice_items');
						frappe.model.set_value(row.doctype, row.name, 'item_type', 'Dialysis Session');
						frappe.model.set_value(row.doctype, row.name, 'item_description', 
							`Dialysis Session - ${frappe.datetime.str_to_user(r.message.session_date)}`);
						frappe.model.set_value(row.doctype, row.name, 'quantity', 1);
						frappe.model.set_value(row.doctype, row.name, 'rate', 500); // Default rate
						frappe.model.set_value(row.doctype, row.name, 'reference_doctype', 'Dialysis Session');
						frappe.model.set_value(row.doctype, row.name, 'reference_name', frm.doc.dialysis_session);
						frm.refresh_field('invoice_items');
					}
				}
			});
		}
	}
});

// Invoice Item child table events
frappe.ui.form.on('Invoice Item', {
	quantity: function(frm, cdt, cdn) {
		calculate_item_amount(frm, cdt, cdn);
	},

	rate: function(frm, cdt, cdn) {
		calculate_item_amount(frm, cdt, cdn);
	},

	invoice_items_remove: function(frm) {
		frm.trigger('calculate_totals');
	}
});

function calculate_item_amount(frm, cdt, cdn) {
	let row = locals[cdt][cdn];
	if (row.quantity && row.rate) {
		frappe.model.set_value(cdt, cdn, 'amount', row.quantity * row.rate);
	}
	frm.trigger('calculate_totals');
}
EOF
"}

