from frappe import _
from frappe.utils import nowdate, add_days, getdate

@frappe.whitelist()
def get_patient_dashboard(patient):
	"""Get comprehensive patient dashboard data"""
	if not patient:
		frappe.throw(_("Patient is required"))

	patient_doc = frappe.get_doc("Patient", patient)

	# Get recent sessions
	recent_sessions = frappe.get_all("Dialysis Session",
		filters={"patient": patient},
		fields=["name", "session_date", "status", "treatment_duration", "dialysis_machine"],
		order_by="session_date desc",
		limit=10
	)

	# Get upcoming appointments
	upcoming_appointments = frappe.get_all("Appointment",
		filters={
			"patient": patient,
			"appointment_date": [">=", nowdate()],
			"status": ["not in", ["Cancelled", "Completed"]]
		},
		fields=["name", "appointment_date", "appointment_time", "machine", "status"],
		order_by="appointment_date asc",
		limit=5
	)

	# Get outstanding invoices
	outstanding_invoices = frappe.get_all("Invoice",
		filters={
			"patient": patient,
			"payment_status": ["!=", "Paid"],
			"docstatus": 1
		},
		fields=["name", "invoice_date", "total_amount", "outstanding_amount", "payment_status"]
	)

	total_outstanding = sum([inv.outstanding_amount for inv in outstanding_invoices])

	# Get recent lab results
	recent_labs = frappe.get_all("Lab Test",
		filters={"patient": patient},
		fields=["name", "test_date", "test_type", "status"],
		order_by="test_date desc",
		limit=5
	)

	return {
		"patient": patient_doc.as_dict(),
		"recent_sessions": recent_sessions,
		"upcoming_appointments": upcoming_appointments,
		"outstanding_invoices": outstanding_invoices,
		"total_outstanding": total_outstanding,
		"recent_labs": recent_labs,
		"statistics": {
			"total_sessions": frappe.db.count("Dialysis Session", {"patient": patient}),
			"completed_sessions": frappe.db.count("Dialysis Session", {"patient": patient, "status": "Completed"}),
			"upcoming_appointments": len(upcoming_appointments),
			"total_outstanding": total_outstanding
		}
	}

@frappe.whitelist()
def get_patient_medical_history(patient):
	"""Get patient's medical history"""
	if not patient:
		frappe.throw(_("Patient is required"))

	patient_doc = frappe.get_doc("Patient", patient)

	return {
		"patient": patient,
		"patient_name": patient_doc.patient_name,
		"medical_history": patient_doc.medical_history if hasattr(patient_doc, 'medical_history') else [],
		"allergies": [item for item in (patient_doc.medical_history or []) if item.condition_type == "Allergy"],
		"chronic_conditions": [item for item in (patient_doc.medical_history or []) if item.condition_type == "Chronic Condition"],
		"surgeries": [item for item in (patient_doc.medical_history or []) if item.condition_type == "Surgery"]
	}

@frappe.whitelist()
def get_patient_treatment_timeline(patient, from_date=None, to_date=None):
	"""Get patient's treatment timeline"""
	if not patient:
		frappe.throw(_("Patient is required"))

	filters = {"patient": patient}

	if from_date:
		filters["session_date"] = [">=", from_date]
	if to_date:
		if "session_date" in filters:
			filters["session_date"] = ["between", [from_date, to_date]]
		else:
			filters["session_date"] = ["<=", to_date]

	sessions = frappe.get_all("Dialysis Session",
		filters=filters,
		fields=["name", "session_date", "status", "pre_dialysis_weight", "post_dialysis_weight", 
				"weight_loss", "treatment_duration", "complications"],
		order_by="session_date desc"
	)

	return {
		"patient": patient,
		"sessions": sessions,
		"total_sessions": len(sessions)
	}

@frappe.whitelist()
def search_patients(query, filters=None):
	"""Search patients by name, ID, or phone"""
	if not query:
		return []

	search_filters = filters or {}

	# Search in multiple fields
	patients = frappe.db.sql("""
		SELECT name, patient_name, mobile_number, national_id, status, age
		FROM `tabPatient`
		WHERE (patient_name LIKE %(query)s 
			OR mobile_number LIKE %(query)s 
			OR national_id LIKE %(query)s
			OR name LIKE %(query)s)
		ORDER BY patient_name
		LIMIT 20
	""", {"query": f"%{query}%"}, as_dict=True)

	return patients

@frappe.whitelist()
def get_patient_vital_trends(patient, days=30):
	"""Get patient's vital signs trends"""
	if not patient:
		frappe.throw(_("Patient is required"))

	from_date = add_days(nowdate(), -int(days))

	# Get sessions with vital signs
	sessions = frappe.get_all("Dialysis Session",
		filters={
			"patient": patient,
			"session_date": [">=", from_date],
			"status": "Completed"
		},
		fields=["name", "session_date"],
		order_by="session_date asc"
	)

	vital_data = []
	for session in sessions:
		# Get vital signs for this session
		vitals = frappe.get_all("Vital Signs Reading",
			filters={"parent": session.name},
			fields=["reading_time", "bp_systolic", "bp_diastolic", "heart_rate", 
					"temperature", "oxygen_saturation"],
			order_by="reading_time asc"
		)

		if vitals:
			vital_data.extend([{
				**vital,
				"session": session.name,
				"session_date": session.session_date
			} for vital in vitals])

	return {
		"patient": patient,
		"from_date": from_date,
		"to_date": nowdate(),
		"vital_signs": vital_data
	}
"}

{"file_path": "frappe-bench/apps/dialysis_center/dialysis_center/api/appointment.py", "initial_content": "import frappe
from frappe import _
from frappe.utils import nowdate, add_days, getdate, get_datetime, time_diff_in_hours
from datetime import datetime, timedelta

@frappe.whitelist()
def get_available_slots(date, machine=None, duration=240):
	"""Get available time slots for a given date and machine"""
	if not date:
		frappe.throw(_("Date is required"))

	duration = int(duration)

	# Define shift timings (can be made configurable)
	shifts = [
		{"time": "08:00:00", "label": "Morning Shift (8:00 AM)"},
		{"time": "14:00:00", "label": "Afternoon Shift (2:00 PM)"},
		{"time": "20:00:00", "label": "Evening Shift (8:00 PM)"}
	]

	available_slots = []

	# Get all machines if not specified
	machines = [machine] if machine else [m.name for m in frappe.get_all("Dialysis Machine", 
		filters={"status": "Available"}, fields=["name"])]

	for m in machines:
		for shift in shifts:
			# Check if slot is available
			is_available = check_slot_availability(date, m, shift["time"], duration)

			if is_available:
				available_slots.append({
					"machine": m,
					"date": date,
					"time": shift["time"],
					"label": shift["label"],
					"duration": duration
				})

	return available_slots

def check_slot_availability(date, machine, time, duration):
	"""Check if a specific slot is available"""
	# Get existing appointments for this slot
	existing = frappe.db.count("Appointment", {
		"appointment_date": date,
		"machine": machine,
		"appointment_time": time,
		"status": ["not in", ["Cancelled", "Completed"]]
	})

	return existing == 0

@frappe.whitelist()
def bulk_schedule_appointments(patient, start_date, frequency="3x per week", duration=240, machine=None, weeks=4):
	"""Bulk schedule appointments for a patient"""
	if not patient or not start_date:
		frappe.throw(_("Patient and start date are required"))

	frequency = int(frequency.split('x')[0]) if 'x' in frequency else 3
	weeks = int(weeks)
	duration = int(duration)

	appointments = []
	current_date = getdate(start_date)
	end_date = add_days(current_date, weeks * 7)

	# Determine days of week (e.g., Monday, Wednesday, Friday for 3x per week)
	days_map = {
		2: [0, 3],  # Monday, Thursday
		3: [0, 2, 4],  # Monday, Wednesday, Friday
		4: [0, 2, 4, 6]  # Monday, Wednesday, Friday, Sunday
	}

	target_days = days_map.get(frequency, [0, 2, 4])

	while current_date <= end_date:
		if current_date.weekday() in target_days:
			# Try to create appointment
			try:
				appt = frappe.get_doc({
					"doctype": "Appointment",
					"patient": patient,
					"appointment_date": current_date,
					"appointment_time": "08:00:00",  # Default to morning
					"duration": duration,
					"machine": machine,
					"status": "Scheduled"
				})
				appt.insert(ignore_permissions=True)
				appointments.append(appt.name)
			except Exception as e:
				frappe.log_error(message=str(e), title=f"Failed to create appointment for {current_date}")

		current_date = add_days(current_date, 1)

	return {
		"created": len(appointments),
		"appointments": appointments
	}

@frappe.whitelist()
def get_daily_schedule(date=None):
	"""Get daily appointment schedule"""
	if not date:
		date = nowdate()

	appointments = frappe.get_all("Appointment",
		filters={"appointment_date": date},
		fields=["name", "patient", "patient_name", "appointment_time", "duration", 
				"machine", "status", "assigned_staff"],
		order_by="appointment_time asc"
	)

	# Group by time slots
	schedule = {}
	for appt in appointments:
		time_slot = appt.appointment_time
		if time_slot not in schedule:
			schedule[time_slot] = []
		schedule[time_slot].append(appt)

	return {
		"date": date,
		"total_appointments": len(appointments),
		"schedule": schedule,
		"appointments": appointments
	}

@frappe.whitelist()
def check_in_appointment(appointment):
	"""Check in a patient for their appointment"""
	if not appointment:
		frappe.throw(_("Appointment is required"))

	doc = frappe.get_doc("Appointment", appointment)
	doc.status = "Checked In"
	doc.checked_in_time = frappe.utils.now_datetime()
	doc.save(ignore_permissions=True)

	return doc

@frappe.whitelist()
def cancel_appointment(appointment, reason):
	"""Cancel an appointment"""
	if not appointment:
		frappe.throw(_("Appointment is required"))

	doc = frappe.get_doc("Appointment", appointment)
	doc.status = "Cancelled"
	doc.notes = (doc.notes or "") + f"\nCancelled: {reason}"
	doc.save(ignore_permissions=True)

	return doc

@frappe.whitelist()
def reschedule_appointment(appointment, new_date, new_time):
	"""Reschedule an appointment"""
	if not appointment or not new_date or not new_time:
		frappe.throw(_("Appointment, new date and new time are required"))

	doc = frappe.get_doc("Appointment", appointment)

	old_date = doc.appointment_date
	old_time = doc.appointment_time

	doc.appointment_date = new_date
	doc.appointment_time = new_time
	doc.notes = (doc.notes or "") + f"\nRescheduled from {old_date} {old_time} to {new_date} {new_time}"
	doc.save(ignore_permissions=True)

	return doc
"}

